function formHTML(c,editor=false){return `<form class="settings-form" novalidate>${FIELDS.map(([title,fields],i)=>`<fieldset><legend>${title}</legend>${fields.map(([key,label,type,a,b])=>`<label class="field ${type==='checkbox'?'check':''}"><span>${label}${type==='range'?`<output data-output="${key}">${c[key]}</output>`:''}</span>${type==='select'?`<select name="${key}">${a.map(([v,l])=>`<option value="${v}" ${c[key]===v?'selected':''}>${l}</option>`).join('')}</select>`:`<input name="${key}" type="${type==='entity'?'text':type}" ${type==='entity'?`list="sensor-options" autocomplete="off" spellcheck="false"`:''} ${type==='range'||type==='number'?`min="${a}" max="${b}" step="${type==='number'?'0.1':'1'}"`:''} ${type==='checkbox'?(c[key]?'checked':''):`value="${esc(c[key])}"`}>`}</label>`).join('')}</fieldset>`).join('')}<datalist id="sensor-options"></datalist><p class="form-status" role="status" aria-live="polite"></p>${editor?'':`<p class="hint">Здесь настройки сохраняются для этой карточки в этом браузере. Для всех устройств меняй их через редактор карточки HA.</p><div class="form-actions"><button type="submit" class="solid">Сохранить настройки</button><button type="button" data-do="reset-local">Вернуть настройки из HA</button></div>`}</form>`;}
