 _state(kind){let id=this._cfg?.[kind==='t'?'temperature_entity':'humidity_entity'],s=this._hass?.states?.[id],v=num(s?.state);if(kind==='h'&&v!==null&&(v<0||v>100))v=null;if(kind==='t'&&s?.attributes?.unit_of_measurement==='°F'&&v!==null)v=(v-32)*5/9;return{v,s,id};}
